const ZONE = {
  N: { hub: "New Delhi", tint: "#bfdbfe", line: "#3b82f6", dot: "#3b82f6" },
  E: { hub: "Kolkata", tint: "#bbf7d0", line: "#22c55e", dot: "#22c55e" },
  W: { hub: "Mumbai", tint: "#fed7aa", line: "#ff8c00", dot: "#ff8c00" },
  S: { hub: "Bengaluru", tint: "#c7d2fe", line: "#6366f1", dot: "#6366f1" }
};

const IndiaNetworkMap = () => {
  const hubs = {
    N: CITIES.find(c => c.n === "New Delhi"),
    W: CITIES.find(c => c.n === "Mumbai"),
    E: CITIES.find(c => c.n === "Kolkata"),
    S: CITIES.find(c => c.n === "Bengaluru")
  };

  return (
    <div id="india-network-map">
      <svg
        viewBox={`0 0 ${VB_W} ${VB_H}`}
        className="inm-svg"
        preserveAspectRatio="xMidYMid meet"
        role="img"
        aria-label="COREAL national partner network across India"
      >
        <defs>
          {/* Halftone dot patterns for zones */}
          {Object.keys(ZONE).map(zk => (
            <pattern
              key={zk}
              id={`inm-dots-${zk}`}
              width="10"
              height="10"
              patternUnits="userSpaceOnUse"
            >
              <rect
                x="1.0"
                y="1.0"
                width="8.0"
                height="8.0"
                rx="1.5"
                fill={ZONE[zk].dot}
                fillOpacity="0.45"
              />
            </pattern>
          ))}

          {/* India Outline Clip */}
          <clipPath id="inm-clip">
            <path d={OUTLINE} />
          </clipPath>

          {/* Zone clips */}
          {Object.keys(ZONE_CLIPS).map(zk => (
            <clipPath key={zk} id={`inm-zone-${zk}`}>
              <path d={ZONE_CLIPS[zk]} />
            </clipPath>
          ))}

          {/* Map Shadow */}
          <filter id="inm-shadow" x="-12%" y="-12%" width="124%" height="124%">
            <feDropShadow dx="0" dy="10" stdDeviation="16" floodColor="#000000" floodOpacity="0.65" />
          </filter>
        </defs>

        {/* Base Map Layers with Zone Colors */}
        <g filter="url(#inm-shadow)">
          {/* Solid white/light base */}
          <path d={OUTLINE} fill="#ffffff" />

          {/* Colored Zones */}
          {Object.keys(ZONE_CLIPS).map(zk => (
            <g key={zk} clipPath={`url(#inm-zone-${zk})`}>
              <path d={OUTLINE} fill={ZONE[zk].tint} fillOpacity="0.85" />
              <path d={OUTLINE} fill={`url(#inm-dots-${zk})`} />
            </g>
          ))}
        </g>

        {/* Outer subtle glow outline */}
        <path
          d={OUTLINE}
          fill="none"
          stroke="#38bdf8"
          strokeWidth="1.8"
          strokeOpacity="0.7"
        />

        {/* Network Connection Lines to Regional Hubs */}
        <g className="inm-network-lines">
          {CITIES.map((c, idx) => {
            if (c.h) return null;
            const hub = hubs[c.z];
            if (!hub) return null;
            return (
              <line
                key={`line-${idx}`}
                x1={c.x}
                y1={c.y}
                x2={hub.x}
                y2={hub.y}
                stroke={ZONE[c.z].line}
                strokeWidth="1.6"
                strokeOpacity="0.75"
                strokeDasharray={c.z === 'W' || c.z === 'N' ? 'none' : '4 3'}
              />
            );
          })}
        </g>

        {/* Inter-hub trunk lines (Delhi - Mumbai - Bengaluru - Kolkata) */}
        <g stroke="#2563eb" strokeWidth="2.8" strokeOpacity="0.9">
          <line x1={hubs.N.x} y1={hubs.N.y} x2={hubs.W.x} y2={hubs.W.y} />
          <line x1={hubs.W.x} y1={hubs.W.y} x2={hubs.S.x} y2={hubs.S.y} />
          <line x1={hubs.S.x} y1={hubs.S.y} x2={hubs.E.x} y2={hubs.E.y} />
          <line x1={hubs.E.x} y1={hubs.E.y} x2={hubs.N.x} y2={hubs.N.y} />
        </g>

        {/* City Dots & Small Labels */}
        {CITIES.map((c, idx) => {
          if (c.h) return null; // hubs rendered separately
          return (
            <g key={`city-${idx}`}>
              <circle
                cx={c.x}
                cy={c.y}
                r="3.5"
                fill="#0f172a"
                stroke="#ffffff"
                strokeWidth="1"
              />
              <text
                x={c.x + 6}
                y={c.y + 3}
                fill="#1e293b"
                fontSize="10"
                fontWeight="600"
                fontFamily="Inter, sans-serif"
              >
                {c.n}
              </text>
            </g>
          );
        })}

        {/* Major Hubs: New Delhi, Mumbai, Bengaluru, Kolkata */}
        {/* New Delhi */}
        <g transform={`translate(${hubs.N.x}, ${hubs.N.y})`}>
          <circle r="16" fill="rgba(59,130,246,0.2)">
            <animate attributeName="r" values="10;22;10" dur="2.4s" repeatCount="indefinite" />
          </circle>
          <circle r="6" fill="#3b82f6" stroke="#ffffff" strokeWidth="2" />
          <rect x="12" y="-14" width="94" height="26" rx="13" fill="#ffffff" filter="drop-shadow(0 2px 5px rgba(0,0,0,0.3))" />
          <text x="24" y="3" fill="#0b1533" fontSize="14" fontWeight="800" fontFamily="Inter, sans-serif">
            New Delhi
          </text>
        </g>

        {/* Mumbai */}
        <g transform={`translate(${hubs.W.x}, ${hubs.W.y})`}>
          <circle r="20" fill="rgba(255,140,0,0.25)">
            <animate attributeName="r" values="12;26;12" dur="2s" repeatCount="indefinite" />
          </circle>
          <circle r="7" fill="#ff8c00" stroke="#ffffff" strokeWidth="2.5" />
          <rect x="14" y="-14" width="76" height="26" rx="13" fill="#ffffff" filter="drop-shadow(0 2px 5px rgba(0,0,0,0.3))" />
          <text x="26" y="3" fill="#0b1533" fontSize="14" fontWeight="800" fontFamily="Inter, sans-serif">
            Mumbai
          </text>
        </g>

        {/* Kolkata */}
        <g transform={`translate(${hubs.E.x}, ${hubs.E.y})`}>
          <circle r="18" fill="rgba(34,197,94,0.2)">
            <animate attributeName="r" values="10;24;10" dur="2.8s" repeatCount="indefinite" />
          </circle>
          <circle r="6" fill="#22c55e" stroke="#ffffff" strokeWidth="2" />
          <rect x="12" y="-14" width="74" height="26" rx="13" fill="#ffffff" filter="drop-shadow(0 2px 5px rgba(0,0,0,0.3))" />
          <text x="24" y="3" fill="#0b1533" fontSize="14" fontWeight="800" fontFamily="Inter, sans-serif">
            Kolkata
          </text>
        </g>

        {/* Bengaluru */}
        <g transform={`translate(${hubs.S.x}, ${hubs.S.y})`}>
          <circle r="18" fill="rgba(99,102,241,0.2)">
            <animate attributeName="r" values="10;24;10" dur="2.6s" repeatCount="indefinite" />
          </circle>
          <circle r="6.5" fill="#ffffff" stroke="#0f1f3d" strokeWidth="3.5" />
          <rect x="14" y="-14" width="94" height="26" rx="13" fill="#ffffff" filter="drop-shadow(0 2px 5px rgba(0,0,0,0.3))" />
          <text x="24" y="3" fill="#0b1533" fontSize="14" fontWeight="800" fontFamily="Inter, sans-serif">
            Bengaluru
          </text>
        </g>
      </svg>
    </div>
  );
};

export default IndiaNetworkMap;
